async function seedLanguages() {
  for (const lang of LANGUAGES) {
    const { id, ...data } = lang;
    await db.collection("programmingLanguages").doc(id).set(data, { merge: true });
    console.log("language:", id);
  }
}

async function seedTopicsForLanguage(langId, modules, contentMap = {}) {
  let order = 0;
  let count = 0;
  for (const { module, topics } of modules) {
    for (const title of topics) {
      order++;
      const topicId = slugify(title);
      const content = contentMap[topicId] || {};
      await db.collection("programmingLanguages").doc(langId).collection("topics").doc(topicId).set({
        title, module, order, status: "published",
        difficulty: content.difficulty || "Beginner",
        estimatedMinutes: content.estimatedMinutes || 20,
        whatYoullLearn: content.whatYoullLearn || [],
        prerequisites: content.prerequisites || [],
        concept: content.concept || "",
        keyPoints: content.keyPoints || [],
        commonMistakes: content.commonMistakes || [],
        interviewTips: content.interviewTips || [],
        realWorldApplications: content.realWorldApplications || [],
        codeExample: content.codeExample || { language: langId === "cpp" ? "cpp" : langId, code: "" },
        mcqs: content.mcqs || [],
        goingDeeper: content.goingDeeper || "",
        assignment: content.assignment || "",
        xpReward: content.xpReward || 25,
        coinReward: content.coinReward || 10,
        practiceProblemIds: [],
      }, { merge: true });
      count++;
    }
  }
  await db.collection("programmingLanguages").doc(langId).set({ topicCount: count }, { merge: true });
  console.log(langId, "-", count, "topics seeded");
}

async function main() {
  await seedLanguages();
  await seedTopicsForLanguage("java", JAVA_MODULES, JAVA_CONTENT);
  const CONTENT_MAPS = {
    c: typeof C_CONTENT !== "undefined" ? C_CONTENT : {},
    cpp: typeof CPP_CONTENT !== "undefined" ? CPP_CONTENT : {},
    javascript: typeof JS_CONTENT !== "undefined" ? JS_CONTENT : {},
    typescript: typeof TS_CONTENT !== "undefined" ? TS_CONTENT : {},
    go: typeof GO_CONTENT !== "undefined" ? GO_CONTENT : {},
    kotlin: typeof KOTLIN_CONTENT !== "undefined" ? KOTLIN_CONTENT : {},
    csharp: typeof CSHARP_CONTENT !== "undefined" ? CSHARP_CONTENT : {},
    rust: typeof RUST_CONTENT !== "undefined" ? RUST_CONTENT : {},
    sql: typeof SQL_CONTENT !== "undefined" ? SQL_CONTENT : {},
    bash: typeof BASH_CONTENT !== "undefined" ? BASH_CONTENT : {},
  };
  for (const [langId, modules] of Object.entries(OTHER_LANGUAGE_MODULES)) {
    // python's content is authored/maintained exclusively by
    // author-python-topics.mjs, not this file - it has no CONTENT_MAPS
    // entry on purpose. Running this loop against it would `.set(...,
    // {merge:true})` every field with its empty-content fallback (""/[]),
    // which still overwrites already-good content since merge only skips
    // fields absent from the payload, not fields explicitly set to a
    // default. Skip it here; run author-python-topics.mjs directly instead.
    if (langId === "python") continue;
    await seedTopicsForLanguage(langId, modules, CONTENT_MAPS[langId] || {});
  }
  console.log("\nDone.");
  process.exit(0);
}

main().catch(e => { console.error(e); process.exit(1); });
